package com.skillsync.web;

import com.skillsync.user.User;
import com.skillsync.user.UserRepository;
import com.skillsync.user.*;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.stream.Collectors;
import java.time.LocalDate;
import org.springframework.security.core.Authentication;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.*;

@Controller
public class AppController {
    private final UserRepository users;
    private final RecommendationService recommendationService;
    private final SkillProfileService skillProfiles;
    private final UserSkillRepository userSkills;
    private final CareerPreferenceRepository preferences;
    private final RoadmapTaskService roadmapTasks;
    public AppController(UserRepository users,RecommendationService service,SkillProfileService skillProfiles,UserSkillRepository userSkills,CareerPreferenceRepository preferences,RoadmapTaskService roadmapTasks){this.users=users;this.recommendationService=service;this.skillProfiles=skillProfiles;this.userSkills=userSkills;this.preferences=preferences;this.roadmapTasks=roadmapTasks;}
    private User current(Authentication auth){return users.findByEmail(auth.getName()).orElseThrow();}
    private List<String> selected(User user){return user.getSkills().isBlank()?List.of():Arrays.stream(user.getSkills().split(",")).map(String::trim).filter(s->!s.isBlank()).toList();}
    @GetMapping("/skills") String skills(Authentication auth,Model model,@RequestParam(required=false) String saved){User u=current(auth);List<UserSkill> inventory=skillProfiles.forUser(u);model.addAttribute("user",u);model.addAttribute("skillGroups",RecommendationService.SKILLS.stream().collect(Collectors.groupingBy(RecommendationService.Skill::category,LinkedHashMap::new,Collectors.toList())));model.addAttribute("selected",inventory.stream().map(UserSkill::getSkillName).toList());model.addAttribute("inventory",inventory);model.addAttribute("proficiencies",Proficiency.values());model.addAttribute("verificationStatuses",List.of(VerificationStatus.SELF_REPORTED));model.addAttribute("evidenceTypes",EvidenceType.values());model.addAttribute("saved",saved!=null);model.addAttribute("evidenceSaved", "evidence".equals(saved));model.addAttribute("skillSaved", "skill".equals(saved));model.addAttribute("error","error".equals(saved));return "skills";}
    @PostMapping("/skills") String saveSkills(@RequestParam(required=false) String[] selected,Authentication auth){User u=current(auth);skillProfiles.addSkills(u,selected);users.save(u);return "redirect:/skills?saved=skill";}
    @PostMapping("/skills/{id}/details") String updateSkill(@PathVariable Long id,@RequestParam Proficiency proficiency,@RequestParam(defaultValue="3") int confidence,@RequestParam(required=false) LocalDate lastPracticed,@RequestParam(required=false) VerificationStatus verificationStatus,Authentication auth){User u=current(auth);if(confidence<1||confidence>5)return "redirect:/skills?saved=error";UserSkill skill=userSkills.findByIdAndUserId(id,u.getId()).orElseThrow();skill.setProficiency(proficiency);skill.setConfidence(confidence);skill.setLastPracticed(lastPracticed);if(verificationStatus==VerificationStatus.SELF_REPORTED)skill.setVerificationStatus(VerificationStatus.SELF_REPORTED);userSkills.save(skill);return "redirect:/skills?saved=skill";}
    @PostMapping("/skills/{id}/evidence") String addEvidence(@PathVariable Long id,@RequestParam EvidenceType type,@RequestParam String title,@RequestParam(required=false) String description,@RequestParam(required=false) String url,Authentication auth){User u=current(auth);UserSkill skill=userSkills.findByIdAndUserId(id,u.getId()).orElseThrow();String safeTitle=title==null?"":title.trim(),safeDescription=description==null?"":description.trim(),safeUrl=url==null?"":url.trim();if(safeTitle.isBlank()||safeTitle.length()>120||safeDescription.length()>1000||safeUrl.length()>500||(!safeUrl.isEmpty()&&!safeUrl.matches("https?://[^\\s]+")))return "redirect:/skills?saved=error";skill.addEvidence(new SkillEvidence(type,safeTitle,safeDescription,safeUrl));if(type==EvidenceType.PROJECT||type==EvidenceType.WORK_EXPERIENCE||type==EvidenceType.INTERNSHIP)skill.setVerificationStatus(VerificationStatus.PROJECT_BACKED);else if(type==EvidenceType.CERTIFICATION)skill.setVerificationStatus(VerificationStatus.CERTIFICATION_BACKED);userSkills.save(skill);return "redirect:/skills?saved=evidence";}
    @GetMapping("/career-paths") String careers(Authentication auth,Model model){User u=current(auth);model.addAttribute("user",u);model.addAttribute("careers",recommendationService.forUser(u));model.addAttribute("careerDomains",recommendationService.careerDomains());model.addAttribute("careerIndustries",recommendationService.careerIndustries());return "career-paths";}
    @GetMapping("/career-comparison") String compareCareers(Authentication auth,Model model,@RequestParam(required=false) String[] careers){User u=current(auth);List<RecommendationService.Recommendation> all=recommendationService.forUser(u);List<String> selected=careers==null?List.of():Arrays.stream(careers).distinct().filter(recommendationService.careerNames()::contains).limit(5).toList();String error=selected.size()>4?"Select between two and four careers.":selected.size()==1?"Choose at least one more career to compare.":null;List<RecommendationService.Recommendation> comparison=selected.size()>=2&&selected.size()<=4?all.stream().filter(r->selected.contains(r.name())).toList():List.of();model.addAttribute("user",u);model.addAttribute("careers",all);model.addAttribute("selectedCareers",selected);model.addAttribute("comparison",comparison);model.addAttribute("selectionError",error);return "career-comparison";}
    @GetMapping("/career-progression") String progression(Authentication auth,Model model,@RequestParam(required=false) String role){User u=current(auth);List<RecommendationService.Recommendation> all=recommendationService.forUser(u);RecommendationService.Recommendation chosen=all.stream().filter(r->r.name().equals(role)).findFirst().orElse(all.getFirst());model.addAttribute("user",u);model.addAttribute("careers",all);model.addAttribute("career",chosen);return "career-progression";}
    @GetMapping("/roadmap") String roadmap(Authentication auth,Model model,@RequestParam(required=false) String role){User u=current(auth);List<RecommendationService.Recommendation> ranked=recommendationService.forUser(u);RecommendationService.Recommendation chosen=ranked.stream().filter(r->r.name().equals(role)).findFirst().orElse(ranked.getFirst());LinkedHashSet<String> priorities=new LinkedHashSet<>(chosen.gaps());priorities.addAll(chosen.partialSkills());List<RoadmapTask> tasks=roadmapTasks.ensure(u,chosen.name(),chosen.gaps(),chosen.partialSkills());List<PlanWeek> planWeeks=new ArrayList<>();int i=0;for(String skill:priorities){int week=++i;planWeeks.add(new PlanWeek(week,roadmapStep(skill,week,chosen.partialSkills().contains(skill)),tasks.stream().filter(t->t.getSkillName().equals(skill)).toList()));}long completed=tasks.stream().filter(RoadmapTask::isCompleted).count();model.addAttribute("user",u);model.addAttribute("recommendation",chosen);model.addAttribute("recommendations",ranked);model.addAttribute("weeks",Math.max(1,planWeeks.size()));model.addAttribute("planWeeks",planWeeks);model.addAttribute("steps",planWeeks.stream().map(PlanWeek::resource).toList());model.addAttribute("roadmapTasks",tasks);model.addAttribute("completedTasks",completed);model.addAttribute("roadmapPercent",tasks.isEmpty()?0:(int)Math.round(completed*100.0/tasks.size()));return "roadmap";}
    @PostMapping("/roadmap/tasks/{id}") String markRoadmapTask(@PathVariable Long id,@RequestParam boolean completed,@RequestParam String role,Authentication auth){roadmapTasks.mark(current(auth),id,completed);return "redirect:/roadmap?role="+URLEncoder.encode(role,StandardCharsets.UTF_8);}
    private Step roadmapStep(String skill,int week,boolean advanced){String url="https://www.open.edu/openlearn/",label="Open University free learning resources";
        switch(skill){case "Java"->{url="https://dev.java/learn/";label="Official Java learning path";}case "Spring Boot"->{url="https://docs.spring.io/spring-boot/tutorial/";label="Spring Boot tutorial";}case "Python"->{url="https://docs.python.org/3/tutorial/";label="Official Python tutorial";}case "SQL"->{url="https://www.postgresql.org/docs/current/tutorial.html";label="PostgreSQL SQL tutorial";}case "Cloud Computing"->{url="https://aws.amazon.com/training/learn-about/cloud-computing/";label="AWS cloud learning";}case "Cybersecurity","Networking"->{url="https://skillsforall.com/";label="Cisco Skills for All";}case "Machine Learning"->{url="https://scikit-learn.org/stable/tutorial/index.html";label="Scikit-learn tutorials";}case "TypeScript"->{url="https://www.typescriptlang.org/docs/";label="TypeScript handbook";}case "JavaScript"->{url="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Guide";label="MDN JavaScript guide";}case "Git"->{url="https://git-scm.com/book/en/v2";label="Pro Git book";}case "UX Research"->{url="https://www.nngroup.com/articles/";label="Nielsen Norman Group articles";}case "Figma"->{url="https://help.figma.com/hc/en-us/categories/360002042553";label="Figma learning resources";}case "Product Strategy","Agile Project Management"->{url="https://www.atlassian.com/agile/product-management";label="Atlassian product management";}case "SEO"->{url="https://developers.google.com/search/docs/fundamentals/seo-starter-guide";label="Google SEO Starter Guide";}case "Data Structures","Algorithms"->{url="https://visualgo.net/en";label="Visualgo algorithm visualizations";}case "Technical Writing"->{url="https://developers.google.com/tech-writing";label="Google technical writing courses";}case "Business Analysis"->{url="https://www.iiba.org/business-analysis-blogs/";label="IIBA business analysis resources";}case "Communication","Presentation Skills"->{url="https://www.toastmasters.org/resources";label="Toastmasters learning resources";}case "Data Visualization"->{url="https://learn.microsoft.com/training/powerplatform/power-bi/";label="Microsoft Power BI training";}case "Data Engineering"->{url="https://learn.microsoft.com/training/browse/?terms=data%20engineering";label="Microsoft data engineering training";}case "AI Literacy","Prompt Engineering","LLM APIs"->{url="https://platform.openai.com/docs/guides/prompt-engineering";label="OpenAI prompting guide";}case "Customer Success"->{url="https://www.gainsight.com/customer-success-resources/";label="Gainsight customer success resources";}case "Talent Acquisition"->{url="https://www.shrm.org/topics-tools/topics/talent-acquisition";label="SHRM talent acquisition resources";}case "Market Research"->{url="https://trends.google.com/trends/";label="Google Trends";}case "Content Strategy"->{url="https://contentmarketinginstitute.com/articles/";label="Content Marketing Institute";}case "Docker"->{url="https://docs.docker.com/get-started/";label="Official Docker getting started guide";}case "Statistics"->{url="https://www.openintro.org/book/os/";label="OpenIntro Statistics textbook";}case "System Design"->{url="https://roadmap.sh/system-design";label="System design learning roadmap";}case "Analytical Thinking"->{url="https://www.open.edu/openlearn/course/view.php?id=13847";label="Open University critical-thinking course";}case "Collaboration"->{url="https://www.atlassian.com/team-playbook";label="Atlassian Team Playbook";}default->{}}
        String detail=advanced?"Skip introductory material; study advanced patterns for "+skill+" and connect them to the selected role.":"Study "+skill+" foundations, practice the core workflow, and produce a small role-relevant deliverable.";
        return new Step(week,skill,detail+" Set aside about 4–6 focused hours this week; adjust the pace to your schedule.",url,label,advanced);}
    @GetMapping("/profile") String profile(Authentication auth,Model model,@RequestParam(required=false) String saved,@RequestParam(required=false) String error){User u=current(auth);CareerPreference pref=preferences.findByUserId(u.getId()).orElseGet(()->preferences.save(new CareerPreference(u)));model.addAttribute("user",u);model.addAttribute("preference",pref);model.addAttribute("careerTypes",List.of("Technical","Nontechnical","Hybrid","Exploring"));model.addAttribute("priorities",List.of("Career growth","Compensation","Technical depth","Work-life balance","Remote opportunities","Leadership opportunities","Creativity","Stability"));model.addAttribute("domains",List.of("Software","AI","Data","Cybersecurity","Cloud","Product","Design","Business","Marketing"));model.addAttribute("careerNames",recommendationService.careerNames());model.addAttribute("saved",saved!=null);model.addAttribute("error",error!=null);return "profile";}
    @PostMapping("/profile") String saveProfile(@RequestParam String fullName,@RequestParam(required=false) String department,@RequestParam(required=false) Double cgpa,Authentication auth){String name=fullName==null?"":fullName.trim(),dept=department==null?"":department.trim();if(name.isBlank()||name.length()>100||dept.length()>255||(cgpa!=null&&(!Double.isFinite(cgpa)||cgpa<0||cgpa>10)))return "redirect:/profile?error=validation";User u=current(auth);u.setFullName(name);u.setDepartment(dept);u.setCgpa(cgpa);users.save(u);return "redirect:/profile?saved";}
    @PostMapping("/profile/preferences") String savePreferences(@RequestParam String careerType,@RequestParam(required=false) String[] priorities,@RequestParam(required=false) String[] domains,@RequestParam(required=false) String targetCareer,@RequestParam(required=false) LocalDate targetDate,Authentication auth){User u=current(auth);Set<String> validTypes=Set.of("Technical","Nontechnical","Hybrid","Exploring");Set<String> validPriorities=Set.of("Career growth","Compensation","Technical depth","Work-life balance","Remote opportunities","Leadership opportunities","Creativity","Stability");Set<String> validDomains=Set.of("Software","AI","Data","Cybersecurity","Cloud","Product","Design","Business","Marketing");if(!validTypes.contains(careerType))return "redirect:/profile?error=validation";String cleanPriorities=Arrays.stream(priorities==null?new String[0]:priorities).filter(validPriorities::contains).distinct().limit(8).collect(Collectors.joining(","));String cleanDomains=Arrays.stream(domains==null?new String[0]:domains).filter(validDomains::contains).distinct().limit(9).collect(Collectors.joining(","));CareerPreference pref=preferences.findByUserId(u.getId()).orElseGet(()->new CareerPreference(u));pref.setCareerType(careerType);pref.setPriorities(cleanPriorities);pref.setDomains(cleanDomains);pref.setTargetCareer(targetCareer!=null&&recommendationService.careerNames().contains(targetCareer)?targetCareer:null);pref.setTargetDate(targetDate);preferences.save(pref);return "redirect:/profile?saved";}
    public record Step(int week,String skill,String description,String resourceUrl,String resourceLabel,boolean advanced){}
    public record PlanWeek(int week,Step resource,List<RoadmapTask> tasks){}
}
